contract.typescript:
interface User {
  id: number;
  name: string;
}

function loadUser(user: User) {
  return findUserById(user.id);
}

contract.typed:
function loadUser(user) {
  if (typeof user.name !== 'string') {
    throw new StrictTypeError('user.name');
  }
  if (typeof user.id !== 'number') {
    throw new StrictTypeError('user.id');
  }
  return findUserById(user.id);
}

